-- Pilgrim's Bounty: increase Elwynn and Tirisfal to 50 Wild Turkeys each.
-- Add 25 per zone to the existing 25; use a 60-second respawn and random roaming.
-- Ground coordinates reuse nearby land-critter spawns; these are reconstructed
-- hunting locations, not an exact retail spawn capture. Event 26 controls all spawns.
-- Reserved creature GUIDs: 9003000-9003049.
DELETE `ge` FROM `game_event_creature` AS `ge` INNER JOIN `creature` AS `c` ON `c`.`guid`=`ge`.`guid`
 WHERE `ge`.`eventEntry`=26 AND `c`.`id`=32820 AND `c`.`guid` BETWEEN 9003000 AND 9003049;
DELETE FROM `creature` WHERE `id`=32820 AND `guid` BETWEEN 9003000 AND 9003049;
UPDATE `creature` AS `c` INNER JOIN `game_event_creature` AS `ge` ON `ge`.`guid`=`c`.`guid`
 SET `c`.`spawntimesecs`=60
 WHERE `c`.`id`=32820 AND `ge`.`eventEntry`=26
 AND (`c`.`guid` BETWEEN 9001011 AND 9001040 OR `c`.`guid` BETWEEN 9002153 AND 9002192
      OR `c`.`guid` BETWEEN 9003000 AND 9003049);
